class Solution(object):
    def isValid(self, s:str) -> bool:
        """
        :type s: str
        :rtype: bool
        """
        stack = []
        
        open_bracket = ['(', '[', '{']
        combine = ["()", "[]", r"{}"]

        if len(s) == 1:
            return False
        
        for c in s:    
            if c in open_bracket:
                stack.append(c)
            elif len(stack) >= 1 and stack[-1] + c in combine:
                stack.pop()
            else:
                return False
        
        if len(stack) >= 1:
            return False
        
        return True

